  Definition fr1_XS (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

  Lemma fr1_XS_scratch : forall LF ff fp, fresh_frame H LF 1 ff fp -> Forall (fs_scratch H LF) (fr1_XS ff fp).
  Proof.
    intros LF ff fp FF. pose proof (fs_scratch_of_fresh H _ _ _ _ FF) as FX. unfold fr1_XS.
    replace (fsz 1) with 128 in FX by reflexivity. replace (fshn 1) with 16 in FX by reflexivity. exact FX.
  Qed.

