Definition mi_segA_post (sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (LF : list fframe) (L : list svce) (R EX ioc regb first allocb schedb lo shi : Z) (j16 : list byte) (ra s0 s1 s2 s3 : word) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m' (XS : list (Z * Z)),
    ms' = MS (mkR (Z_to_bv 64 AMI_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 regb) (Z_to_bv 64 (bv_unsigned sp + -56)) (Z_to_bv 64 P_A_CREATE_SSVC) (Z_to_bv 64 ioc) a4 a5 a6 a7
                  s2 (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_DO_USE_SERVICE) fc None m' (seg_rom asegs)
    /\ Forall (fs_scratch H LF) XS
    /\ munch ([(lo, bv_unsigned sp)]%Z ++ XS) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells asegs m' (bv_unsigned sp + -64) [C8 (Z_to_bv 64 0)]
    /\ rw_cells asegs m' (bv_unsigned sp + -56) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 AG_ID_SSVC)]
    /\ rw_cells asegs m' (bv_unsigned sp + -40) [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells asegs m' EX (AnyExecCells EX ioc j16)
    /\ ro_cells asegs m' ioc (IoCtxCells allocb regb schedb)
    /\ ARegistry LB m' regb ioc first 0
    /\ ASvcChain m' first L
    /\ AAllocImpl LB m' allocb /\ AXStatics2 m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma mi_segA : forall (ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LB : list block) (LF : list fframe) (L : list svce)
    (R EX ioc regb first allocb schedb lo shi : Z) (j16 : list byte),
  rw_cells asegs m EX (AnyExecCells EX ioc j16) -> aapp EX 56 -> fsobj H LF EX 56 -> EX mod 8 = 0 -> accessible m EX 56 -> 0 < EX ->
  ro_cells asegs m ioc (IoCtxCells allocb regb schedb) -> aapp ioc 24 -> fsobj H LF ioc 24 -> ioc mod 8 = 0 -> accessible m ioc 24 -> 0 < ioc ->
  ARegistry LB m regb ioc first 0 -> fsobj H LF regb NEWSZ_REG ->
  ASvcChain m first L -> Forall (fun e => fsobj H LF (se_addr e) 48 /\ aapp (se_addr e) 48) L ->
  AAllocImpl LB m allocb -> fsobj H LF allocb SZ_ALLOCIMPL -> AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp) -> lo + 64 + AANYEX_QUERY_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  evt asegs (mi_segA_post sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF L R EX ioc regb first allocb schedb lo shi j16 ra s0 s1 s2 s3 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 0) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SSVC_MAKE_IMPL) fc None m (seg_rom asegs)).
